(async()=>{const E=window.__echoes; const rows=[];
 for(let i=0;i<15;i++){
   const s=E.cmd('runState'); if(s.active) E.cmd('endRun','victory');
   await new Promise(r=>setTimeout(r,60));
   E.cmd('startRun'); await new Promise(r=>setTimeout(r,60));
   E.cmd('skipToRoom',7); await new Promise(r=>setTimeout(r,200));
   const v=E.cmd('runState');
   const st=v.shop?v.shop.stock:[];
   const pr=st.map(x=>x.price);
   const pairs=[]; for(let a=0;a<pr.length;a++)for(let b=a+1;b<pr.length;b++)pairs.push(pr[a]+pr[b]);
   rows.push({wallet:v.wallet, n:st.length, prices:pr.join('/'), rar:st.map(x=>x.rarity).join('/'),
     anyTwoAff: pairs.length? pairs.every(x=>x<=v.wallet):null, all3:pr.reduce((a,b)=>a+b,0)<=v.wallet});
 }
 E.cmd('endRun','victory');
 const bad=rows.filter(r=>r.wallet!==72||r.n!==3||r.prices!=='25/30/35'||!r.anyTwoAff||r.all3);
 return {n:rows.length, bad, sample:rows.slice(0,3)};})()
